/**
 * The rollup job's work list, most recently measured first: every write nudges
 * `measured_at`, so the top of this list is where the tenants that are
 * actually changing — and therefore drifting — are.
 */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizationUsage.orgId })
    .from(organizationUsage)
    .orderBy(desc(organizationUsage.measuredAt))
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}

input.new_string:
/**
 * The rollup job's work list: live organizations whose counters were
 * recounted longest ago, at most `limit` of them. `measured_at` moves only
 * when `recomputeUsage` runs, so a delta from `incrementUsage` does not
 * change a workspace's place. A workspace with no usage row has never been
 * recounted and sorts first (SQLite orders NULLs first on ASC).
 */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizations.id })
    .from(organizations)
    .leftJoin(organizationUsage, eq(organizationUsage.orgId, organizations.id))
    .where(isNull(organizations.archivedAt))
    .orderBy(asc(organizationUsage.measuredAt), asc(organizations.id))
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}

